                        target1:"在第二次世界大戰期間，有一隻名為山姆的黑白花貓，寫下了航海史上最不可思議的生存奇蹟。牠最初效力於德國海軍的王牌戰艦「俾斯麥號」，然而在一次激烈海戰中戰艦沉沒，山姆抱著一塊木板在海上漂流，被英國皇家海軍救起，並收編為吉祥物。沒想到，牠隨後服役的英國戰艦「哥薩克人號」以及航空母艦「皇家方舟號」，竟然也陸續在幾個月內遭到魚雷擊沉。神奇的是，每次沉船事故發生後，山姆總能毫髮無傷地在浮木上被友軍撈起。因為連續經歷三次盟軍與敵軍的重大沉船卻都奇蹟生還，牠最終獲得了「不沉的山姆」這個響亮封號，並被送回陸地安享晚年。"
