                        wpm_min:82,
                        acc_min:92,
                        target1:"你能想像一根胡蘿蔔竟然能引發一場國際軍事衝突嗎？在一九八四年的歐洲，一艘瑞典的潛艇正在波羅的海執行秘密巡邏任務。突然間，聲納員監測到水底傳來一陣極其怪異、且規律的「啪嗒啪嗒」聲。由於當時冷戰陰影籠罩，瑞典軍方高度緊張，懷疑這是蘇聯最新研發的隱形間諜潛艇在附近刺探軍情！為了揪出這個神祕的威脅，瑞典海軍展開了長達數年的大規模搜捕，耗費了數百萬美元的國防預算。直到最後，科學家介入調查才揭開了這個荒謬的真相。原來，那個神祕的聲音根本不是什麼蘇聯高科技潛艇，而是一群鯡魚在水下排氣「放屁」的聲音！其實，鯡魚會透過放屁發出高頻聲音來跟同伴溝通。瑞典海軍知道真相後簡直哭笑不得，不過這項發現也讓那位研究鯡魚放屁的科學家，榮獲了當年的「搞笑諾貝爾獎」呢！"
