                        target1:"一九零六年的德國，發生了一起震驚全國的「科佩尼克上尉」事件。一名剛剛出獄、窮困潦倒的鞋匠威廉，在二手市場買了一套破舊的普魯士陸軍上尉制服。他穿上制服後，竟然跑到街上隨機攔截了兩隊正在行軍的士兵，並用威嚴的口氣命令：「全體注意！跟我走！」在當時極度崇尚軍人體制的德國，士兵們完全不敢質疑，立刻乖乖聽令。威廉就這樣帶著軍隊佔領了當地的市政廳，不僅把市長給拘捕起來，還堂而皇之地沒收了市庫裡的所有現金。最諷刺的是，整個過程中上至市長、下至警察和市民，竟然沒有任何一個人懷疑這位「上尉」的真偽，直到他拿著錢溜之大吉。最後，這個大膽的鞋匠幾天後就被抓了，但當時的德國皇帝威廉二世聽到這件事後，不但沒有生氣，反而哈哈大笑，認為這證明了自己的軍隊多麼服從紀律，最後甚至特赦了這個鞋匠，讓他成了民間英雄！"
