                        target1:"來自克羅埃西亞的音樂老師弗蘭，被公認為世界上最傳奇的男人。他的一生經歷了七次與死神擦身而過的恐怖災難！一九六二年，他搭乘的火車脫軌掉進冰冷的河裡，眾人溺斃但他奇蹟生還；隔年，他第一次搭飛機，機艙門竟然在半空炸開，他被吸出機外，卻幸運地掉在乾草堆上活了下來。隨後幾年，他還經歷了巴士翻車墜河、開車時引擎爆炸、在路邊被巴士撞飛等慘劇，但每一次他都只受了輕傷！更瘋狂的是，在經歷了這麼多倒楣事後，他在七十三歲那年，第一次買彩券就中了高達一百萬美元的頭獎！他感嘆地說：「你可以說我是世界上最倒楣的人，但同時，我也是最幸運的人！」"
