                        wpm_min:98,
                        acc_min:93,
                        target1:"在幽暗的海底裡，生活著一種體型只有幾公分的大師級殺手，叫做「手槍蝦」。牠擁有一隻巨大且構造特殊的巨螯，當牠發現獵物時，會以極快的速度將巨螯用力闔上。這個動作並不是要去夾碎獵物，而是會噴射出一道時速高達一百公里的高速水流！這道水流會在水中產生一個極微小的「低壓氣泡」。當氣泡在千分之一秒內破裂時，會產生高達兩百一十八分貝的轟然巨響，甚至釋放出接近太陽表面溫度的攝氏四千多度高溫。這股強大的衝擊波能瞬間把前方的魚蝦震暈甚至炸碎，讓手槍蝦可以悠閒地走過去享用美味的午餐。手槍蝦夾螯產生的聲音比真的手槍發射（約 150 分貝）還要大聲！當成千上萬隻手槍蝦聚集在一起時，牠們產生的集體噪音甚至能干擾海軍潛艇的聲納探測，讓軍方非常頭痛呢！"
