                        level:"✧✧✧✧✧",
                        wpm_min:106,
                        acc_min:93,
                        target1:"世界上最難被消滅的動物，絕對非「水熊蟲」莫屬。這種必須用顯微鏡才看得到的小生物，具備了地表最強悍的生存特技。當面臨極端環境時，牠們會排空體內百分之九十九的水分，將自己捲縮成一團，進入一種名為「隱生」的假死狀態。在此狀態下，牠們可以承受零下兩百度的極低溫，也能忍受一百五十度的高溫；甚至連致命的輻射線、地球最深海溝的超高水壓，都無法對牠們造成傷害。科學家甚至曾把水熊蟲送上太空，讓牠們直接暴露在沒有空氣、充滿強烈宇宙射線的真空環境中，結果十天後回到地球，牠們一泡水竟然又活蹦亂跳了！"
