                        target1:"在北美洲的森林裡，生活著一種行為讓人目瞪口呆的昆蟲，叫做「放屁甲蟲（射砲步甲）」。當牠遭遇到鳥類或青蛙等天敵攻擊時，牠絕對不會坐以待斃。牠的腹部內建了兩個獨立的化學儲存槽，分別裝著過氧化氫與對苯二酚。一旦危險來臨，甲蟲會把這兩種化學物質擠進特製的「燃燒室」中，瞬間引發劇烈反應，並朝著敵人的臉噴射出一股溫度高達攝氏一百度的酸性化學毒霧！這股劇毒熱流不僅味道極其惡臭，還會伴隨著劈啪的爆炸聲。更厲害的是，牠的尾部噴嘴還可以像戰鬥機的機砲一樣，進行一百八十度的全方位旋轉準確瞄準。放屁甲蟲噴射出的毒霧威力驚人，有些倒楣的青蛙剛把牠吞進肚子裡，就會被牠在胃袋裡「瘋狂開砲」，最後青蛙因為受不了高溫與劇毒，只能痛苦地把牠整隻吐出來。甲蟲就這樣大搖大擺地從捕食者嘴裡死裡逃生！"
